-- Highway Tires online-style inventory catalog repopulation
-- Generated from the inventory seed generator and supporting inventory migrations.
-- Covers January 1, 2023 through August 16, 2026.
-- Import after the core database/schema exists.
USE hwtires;


-- Source: database\all_branches_inventory_migration.sql

-- Enable inventory for every branch.
-- Run once on existing deployments after pulling the branch management update.

ALTER TABLE branches
    MODIFY has_inventory BOOLEAN DEFAULT TRUE;

UPDATE branches
SET has_inventory = 1
WHERE has_inventory <> 1 OR has_inventory IS NULL;

-- Source: database\inventory_product_details_migration.sql

USE hwtires;

DROP PROCEDURE IF EXISTS migrate_inventory_product_details;

DELIMITER $$

CREATE PROCEDURE migrate_inventory_product_details()
BEGIN
    IF (
        SELECT COUNT(*)
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'inventory_items'
          AND COLUMN_NAME = 'model'
    ) = 0 THEN
        ALTER TABLE inventory_items ADD COLUMN model VARCHAR(100) NULL AFTER brand;
    END IF;

    IF (
        SELECT COUNT(*)
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'inventory_items'
          AND COLUMN_NAME = 'serial_number'
    ) = 0 THEN
        ALTER TABLE inventory_items ADD COLUMN serial_number VARCHAR(120) NULL AFTER sku;
    END IF;

    IF (
        SELECT COUNT(*)
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'inventory_items'
          AND COLUMN_NAME = 'manufacturing_date'
    ) = 0 THEN
        ALTER TABLE inventory_items ADD COLUMN manufacturing_date DATE NULL AFTER serial_number;
    END IF;

    IF (
        SELECT COUNT(*)
        FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'inventory_items'
          AND INDEX_NAME = 'idx_serial_number'
    ) = 0 THEN
        ALTER TABLE inventory_items ADD INDEX idx_serial_number (serial_number);
    END IF;

    IF (
        SELECT COUNT(*)
        FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'inventory_items'
          AND INDEX_NAME = 'idx_manufacturing_date'
    ) = 0 THEN
        ALTER TABLE inventory_items ADD INDEX idx_manufacturing_date (manufacturing_date);
    END IF;
END$$

DELIMITER ;

CALL migrate_inventory_product_details();
DROP PROCEDURE migrate_inventory_product_details;

UPDATE inventory_items
SET serial_number = sku
WHERE serial_number IS NULL
  AND sku IS NOT NULL
  AND sku <> '';

-- Source: database\hwtires_inventory_seed_2023_reset.sql

-- Highway Tires inventory yearly seed for 2023
-- Generated by database/generate_inventory_yearly_seed.php
USE hwtires;

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM transfer_notifications;
DELETE FROM inter_branch_transfer_requests;
DELETE FROM inventory_transactions;
DELETE FROM inventory_items;
ALTER TABLE inventory_transactions AUTO_INCREMENT = 1;
ALTER TABLE inventory_items AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS = 1;

UPDATE branches SET has_inventory = 1 WHERE id IN (1, 2, 3);







































